<span class="line"><span class="token keyword">static</span> <span class="token class-name">lv_color_t</span> <span class="token function">chart_sample_color_on_axis</span><span class="token punctuation">(</span><span class="token class-name">lv_coord_t</span> y<span class="token punctuation">,</span> <span class="token class-name">lv_coord_t</span> y_start<span class="token punctuation">,</span> <span class="token class-name">lv_coord_t</span> y_end<span class="token punctuation">,</span></span>
